const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderWorkflowState({title,description='',action='',kind='initial',headingLevel=3}={}){const heading=headingLevel===2?'h2':'h3';return '<section class="workflow-empty" data-workflow-state="'+esc(kind)+'"><span class="workflow-empty-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 6h6l2 2h8v12H4Z"/><path d="M8 12h8M8 16h5"/></svg></span><'+heading+'>'+esc(title)+'</'+heading+'>'+(description?'<p>'+esc(description)+'</p>':'')+(action?'<div class="workflow-empty-actions">'+action+'</div>':'')+'</section>';}
export function renderFilterSummary(items,clear=''){const active=items.filter(item=>item.value!==null&&item.value!==undefined&&item.value!=='');return active.length?'<div class="workflow-filter-summary" role="group" aria-label="적용 중인 필터">'+active.map(item=>'<span><small>'+esc(item.label)+'</small>'+(item.remove?'<span class="workflow-filter-value" title="'+esc(item.value)+'">'+esc(item.value)+'</span>'+item.remove:esc(item.value))+'</span>').join('')+clear+'</div>':'';}
